package com.bank.flink.mon;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Records a time series of metric snapshots (as a reporter would feed Prometheus).
class MetricsCollector {
    private static final Logger log = Logger.getLogger(MetricsCollector.class.getName());
    private final List<MetricSnapshot> series = new ArrayList<>();

    void record(MetricSnapshot s) {
        series.add(s);
        log.fine(() -> "recorded cpDur=" + s.checkpointDurationMs
                + " state=" + s.stateSizeMb + " lag=" + s.kafkaLag
                + " bp=" + s.fraudOperatorBackpressureMsPerSec);
    }

    List<MetricSnapshot> series() { return series; }
}
