package com.bank.flink.mon;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Applies trend-based rules to the metric series and raises alerts.
class AlertEvaluator {
    private static final Logger log = Logger.getLogger(AlertEvaluator.class.getName());

    private static final long CHECKPOINT_INTERVAL_MS = 60000; // 60s interval
    private static final int BACKPRESSURE_THRESHOLD = 500;    // ms/sec
    private static final long LAG_THRESHOLD = 100000;

    List<String> evaluate(List<MetricSnapshot> series) {
        List<String> alerts = new ArrayList<>();
        for (int i = 1; i < series.size(); i++) {
            MetricSnapshot prev = series.get(i - 1);
            MetricSnapshot cur = series.get(i);

            // Rising checkpoint duration approaching the interval = danger.
            if (cur.checkpointDurationMs > prev.checkpointDurationMs
                    && cur.checkpointDurationMs > CHECKPOINT_INTERVAL_MS * 0.8) {
                String a = "ALERT CheckpointDurationRising " + cur.checkpointDurationMs
                        + "ms approaching interval " + CHECKPOINT_INTERVAL_MS + "ms";
                alerts.add(a);
                log.severe(() -> a);
            }
            // Monotonically growing state with no plateau = leak.
            if (cur.stateSizeMb > prev.stateSizeMb) {
                long delta = cur.stateSizeMb - prev.stateSizeMb;
                String a = "ALERT StateSizeGrowing +" + delta + "MB (now " + cur.stateSizeMb + "MB)";
                alerts.add(a);
                log.warning(() -> a);
            }
            // Sustained backpressure on the fraud operator = bottleneck.
            if (cur.fraudOperatorBackpressureMsPerSec > BACKPRESSURE_THRESHOLD) {
                String a = "ALERT OperatorBackpressured fraud op "
                        + cur.fraudOperatorBackpressureMsPerSec + "ms/sec busy";
                alerts.add(a);
                log.severe(() -> a);
            }
            // Rising Kafka lag = falling behind input.
            if (cur.kafkaLag > LAG_THRESHOLD && cur.kafkaLag > prev.kafkaLag) {
                String a = "ALERT KafkaConsumerLagHigh " + cur.kafkaLag;
                alerts.add(a);
                log.severe(() -> a);
            }
        }
        return alerts;
    }
}
