package com.bank.flink.mon;

import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class MonitoringDemo {
    private static final Logger log = Logger.getLogger(MonitoringDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        MetricsCollector collector = new MetricsCollector();
        long t = 0, min = 60000;

        // Healthy start, then gradual degradation: state grows, checkpoints slow,
        // the fraud operator backs up, lag rises.
        collector.record(new MetricSnapshot(t,             5000,   800,   5000,   50));
        collector.record(new MetricSnapshot(t += min,     12000,  1500,  10000,  120));
        collector.record(new MetricSnapshot(t += min,     30000,  2600,  40000,  400));
        collector.record(new MetricSnapshot(t += min,     52000,  4100, 150000,  700));

        AlertEvaluator evaluator = new AlertEvaluator();
        List<String> alerts = evaluator.evaluate(collector.series());
        log.info("total alerts raised = " + alerts.size());
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel().getName(), r.getMessage());
    }
}
